<?php
declare(strict_types=1);

function mg_investment_relations_detail(PDO $pdo,string $roundPublicId): array
{
    $round=mg_investment_closing_round($pdo,$roundPublicId);$periods=$pdo->prepare('SELECT * FROM investment_reporting_periods WHERE round_id=? ORDER BY starts_at DESC,id DESC');$periods->execute([(int)$round['id']]);$snapshots=$pdo->prepare('SELECT s.*,p.public_id AS period_public_id,p.period_name,p.period_type FROM investment_reporting_snapshots s INNER JOIN investment_reporting_periods p ON p.id=s.reporting_period_id WHERE p.round_id=? ORDER BY p.starts_at DESC,s.version_number DESC');$snapshots->execute([(int)$round['id']]);$actuals=$pdo->prepare('SELECT a.*,p.public_id AS period_public_id,p.period_name FROM investment_use_of_funds_actuals a LEFT JOIN investment_reporting_periods p ON p.id=a.reporting_period_id WHERE a.round_id=? ORDER BY a.spent_at DESC,a.id DESC');$actuals->execute([(int)$round['id']]);$reconciliation=$pdo->prepare('SELECT * FROM investment_cap_reconciliation_snapshots WHERE round_id=? ORDER BY created_at DESC LIMIT 50');$reconciliation->execute([(int)$round['id']]);$packets=$pdo->prepare('SELECT p.*,u.full_name,u.display_name,u.email FROM investment_closing_packets p INNER JOIN users u ON u.id=p.investor_user_id WHERE p.round_id=? ORDER BY p.updated_at DESC');$packets->execute([(int)$round['id']]);$documents=$pdo->prepare('SELECT d.*,p.public_id AS packet_public_id,p.packet_name,u.full_name,u.display_name,u.email FROM investment_closing_documents d INNER JOIN investment_closing_packets p ON p.id=d.packet_id INNER JOIN users u ON u.id=p.investor_user_id WHERE p.round_id=? ORDER BY p.updated_at DESC,d.title');$documents->execute([(int)$round['id']]);return ['round'=>$round,'periods'=>$periods->fetchAll(PDO::FETCH_ASSOC),'snapshots'=>$snapshots->fetchAll(PDO::FETCH_ASSOC),'use_of_funds_actuals'=>$actuals->fetchAll(PDO::FETCH_ASSOC),'reconciliation'=>$reconciliation->fetchAll(PDO::FETCH_ASSOC),'packets'=>$packets->fetchAll(PDO::FETCH_ASSOC),'documents'=>$documents->fetchAll(PDO::FETCH_ASSOC)];
}

function mg_investment_reporting_period_save(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.relations.manage');$round=mg_investment_closing_round($pdo,mg_investment_text($input['round_id']??'',36,36,'Round identifier'));$publicId=trim((string)($input['period_id']??''));$types=['monthly','quarterly','annual','milestone','closing','other'];$statuses=['planning','collecting','draft','internal_review','approved','published','archived'];$type=(string)($input['period_type']??'quarterly');$status=(string)($input['status']??'planning');if(!in_array($type,$types,true)||!in_array($status,$statuses,true))throw new MgInvestmentException('Invalid reporting period type or status.');$starts=mg_investment_date($input['starts_at']??null);$ends=mg_investment_date($input['ends_at']??null);if($starts===null||$ends===null)throw new MgInvestmentException('Reporting period start and end dates are required.');if(strtotime($ends)<strtotime($starts))throw new MgInvestmentException('Reporting period end date cannot be before the start date.');$actorId=(int)$actor['id'];
    if($publicId===''){$publicId=mg_investment_uuid();$pdo->prepare('INSERT INTO investment_reporting_periods (public_id,round_id,period_name,period_type,starts_at,ends_at,due_at,status,published_at,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES (?,?,?,?,DATE(?),DATE(?),?,?,IF(?="published",NOW(),NULL),?,?,NOW(),NOW())')->execute([$publicId,(int)$round['id'],mg_investment_text($input['period_name']??'',180,2,'Period name'),$type,$starts,$ends,mg_investment_date($input['due_at']??null),$status,$status,$actorId,$actorId]);}
    else{$q=$pdo->prepare('SELECT id FROM investment_reporting_periods WHERE public_id=? AND round_id=? LIMIT 1');$q->execute([mg_investment_text($publicId,36,36,'Period identifier'),(int)$round['id']]);$id=(int)$q->fetchColumn();if($id<1)throw new MgInvestmentException('Investor reporting period not found.',404);$pdo->prepare('UPDATE investment_reporting_periods SET period_name=?,period_type=?,starts_at=DATE(?),ends_at=DATE(?),due_at=?,status=?,published_at=IF(?="published",COALESCE(published_at,NOW()),published_at),updated_by_user_id=?,updated_at=NOW() WHERE id=?')->execute([mg_investment_text($input['period_name']??'',180,2,'Period name'),$type,$starts,$ends,mg_investment_date($input['due_at']??null),$status,$status,$actorId,$id]);}
    mg_audit('investment_reporting_period_saved','investment_reporting_period',['period_id'=>$publicId,'round_id'=>$round['public_id'],'status'=>$status],$actorId);return ['relations'=>mg_investment_relations_detail($pdo,(string)$round['public_id']),'dashboard'=>mg_investment_closing_dashboard($pdo,['round_id'=>$round['public_id']])];
}

function mg_investment_reporting_snapshot_save(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.relations.manage');$periodPublicId=mg_investment_text($input['period_id']??'',36,36,'Reporting period identifier');$q=$pdo->prepare('SELECT p.*,r.public_id AS round_public_id,r.workspace_id FROM investment_reporting_periods p INNER JOIN investment_rounds r ON r.id=p.round_id WHERE p.public_id=? LIMIT 1');$q->execute([$periodPublicId]);$period=$q->fetch(PDO::FETCH_ASSOC);if(!$period)throw new MgInvestmentException('Investor reporting period not found.',404);$status=(string)($input['status']??'draft');if(!in_array($status,['draft','internal_review','approved','published','superseded','archived'],true))throw new MgInvestmentException('Invalid reporting snapshot status.');$metrics=is_array($input['metrics']??null)?$input['metrics']:[];$use=is_array($input['use_of_funds']??null)?$input['use_of_funds']:[];$milestones=is_array($input['milestones']??null)?$input['milestones']:[];$risks=is_array($input['risks']??null)?$input['risks']:[];$actorId=(int)$actor['id'];$n=$pdo->prepare('SELECT COALESCE(MAX(version_number),0)+1 FROM investment_reporting_snapshots WHERE reporting_period_id=?');$n->execute([(int)$period['id']]);$version=(int)$n->fetchColumn();$publicId=mg_investment_uuid();$pdo->beginTransaction();try{if($status==='published')$pdo->prepare('UPDATE investment_reporting_snapshots SET status="superseded" WHERE reporting_period_id=? AND status="published"')->execute([(int)$period['id']]);$pdo->prepare('INSERT INTO investment_reporting_snapshots (public_id,reporting_period_id,version_number,headline,narrative,metrics_json,use_of_funds_json,milestones_json,risks_json,status,approved_by_user_id,approved_at,published_at,created_by_user_id,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,IF(? IN ("approved","published"),?,NULL),IF(? IN ("approved","published"),NOW(),NULL),IF(?="published",NOW(),NULL),?,NOW())')->execute([$publicId,(int)$period['id'],$version,mg_investment_text($input['headline']??'',220,2,'Report headline'),mg_investment_long_text($input['narrative']??'',30000)?:null,mg_investment_json_encode($metrics),mg_investment_json_encode($use),mg_investment_json_encode($milestones),mg_investment_json_encode($risks),$status,$status,$actorId,$status,$status,$actorId]);$pdo->prepare('UPDATE investment_reporting_periods SET status=?,published_at=IF(?="published",COALESCE(published_at,NOW()),published_at),updated_by_user_id=?,updated_at=NOW() WHERE id=?')->execute([$status==='published'?'published':($status==='approved'?'approved':$period['status']),$status,$actorId,(int)$period['id']]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}mg_audit('investment_reporting_snapshot_saved','investment_reporting_snapshot',['snapshot_id'=>$publicId,'period_id'=>$periodPublicId,'version'=>$version,'status'=>$status],$actorId);return ['relations'=>mg_investment_relations_detail($pdo,(string)$period['round_public_id']),'dashboard'=>mg_investment_closing_dashboard($pdo,['round_id'=>$period['round_public_id']])];
}

function mg_investment_use_of_funds_actual_save(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.relations.manage');$round=mg_investment_closing_round($pdo,mg_investment_text($input['round_id']??'',36,36,'Round identifier'));$periodId=null;if(!empty($input['period_id'])){$q=$pdo->prepare('SELECT id FROM investment_reporting_periods WHERE public_id=? AND round_id=? LIMIT 1');$q->execute([mg_investment_text($input['period_id'],36,36,'Period identifier'),(int)$round['id']]);$periodId=(int)$q->fetchColumn()?:null;}if(empty($input['spent_at']))throw new MgInvestmentException('Use-of-funds date is required.');$publicId=trim((string)($input['actual_id']??''));$actorId=(int)$actor['id'];if($publicId===''){$publicId=mg_investment_uuid();$pdo->prepare('INSERT INTO investment_use_of_funds_actuals (public_id,round_id,reporting_period_id,budget_category,amount_cents,spent_at,description,evidence_reference,investor_visible,created_by_user_id,created_at,updated_at) VALUES (?,?,?,?,?,DATE(?),?,?,?,?,NOW(),NOW())')->execute([$publicId,(int)$round['id'],$periodId,mg_investment_text($input['budget_category']??'',180,2,'Budget category'),mg_investment_money($input['amount']??0),mg_investment_date($input['spent_at']),mg_investment_long_text($input['description']??'',6000,5,'Description'),mg_investment_text($input['evidence_reference']??'',220)?:null,mg_investment_bool($input['investor_visible']??false)?1:0,$actorId]);}else{$q=$pdo->prepare('SELECT id FROM investment_use_of_funds_actuals WHERE public_id=? AND round_id=? LIMIT 1');$q->execute([mg_investment_text($publicId,36,36,'Actual identifier'),(int)$round['id']]);$id=(int)$q->fetchColumn();if($id<1)throw new MgInvestmentException('Use-of-funds actual not found.',404);$pdo->prepare('UPDATE investment_use_of_funds_actuals SET reporting_period_id=?,budget_category=?,amount_cents=?,spent_at=DATE(?),description=?,evidence_reference=?,investor_visible=?,updated_at=NOW() WHERE id=?')->execute([$periodId,mg_investment_text($input['budget_category']??'',180,2,'Budget category'),mg_investment_money($input['amount']??0),mg_investment_date($input['spent_at']),mg_investment_long_text($input['description']??'',6000,5,'Description'),mg_investment_text($input['evidence_reference']??'',220)?:null,mg_investment_bool($input['investor_visible']??false)?1:0,$id]);}mg_audit('investment_use_of_funds_actual_saved','investment_use_of_funds',['actual_id'=>$publicId,'round_id'=>$round['public_id']],$actorId);return ['relations'=>mg_investment_relations_detail($pdo,(string)$round['public_id']),'dashboard'=>mg_investment_closing_dashboard($pdo,['round_id'=>$round['public_id']])];
}

function mg_investment_closing_ai_draft(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.ai');$type=mg_investment_text($input['draft_type']??'closing_readiness',80,3,'Draft type');$allowed=['closing_readiness','missing_documents','investor_closing_briefing','compliance_deadlines','closing_instructions','closing_announcement','post_close_update','scenario_actual','use_of_funds_variance'];if(!in_array($type,$allowed,true))throw new MgInvestmentException('Invalid closing AI action.');$round=mg_investment_closing_round($pdo,mg_investment_text($input['round_id']??'',36,36,'Round identifier'));$context=['draft_type'=>$type,'round'=>['public_id'=>$round['public_id'],'public_name'=>$round['public_name'],'status'=>$round['status'],'instrument_type'=>$round['instrument_type'],'target_raise_cents'=>(int)$round['target_raise_cents'],'signed_cents'=>(int)$round['signed_cents'],'funded_cents'=>(int)$round['funded_cents'],'counsel_status'=>$round['counsel_status']],'instruction'=>mg_investment_long_text($input['instruction']??'',6000)];$summary=mg_investment_closing_dashboard($pdo,['round_id'=>$round['public_id']]);$context['closing_summary']=$summary['summary'];$context['records']=array_map(static fn($r)=>['record_id'=>$r['public_id'],'investor'=>$r['display_name']?:$r['full_name'],'status'=>$r['status'],'signed_amount_cents'=>(int)$r['signed_amount_cents'],'verified_funded_cents'=>(int)$r['verified_funded_cents'],'packet_count'=>(int)$r['packet_count'],'pending_verifications'=>(int)$r['pending_verifications']],$summary['records']);$context['compliance']=array_map(static fn($c)=>['title'=>$c['title'],'status'=>$c['status'],'due_at'=>$c['due_at'],'counsel_required'=>(bool)$c['counsel_required']],$summary['compliance']);$model=mg_investment_claude_model($pdo);$publicId=mg_investment_uuid();$pdo->prepare('INSERT INTO investment_ai_analyses (public_id,workspace_id,round_id,requested_by_user_id,provider,model,analysis_type,input_snapshot_json,status,created_at) VALUES (?,?,?,? ,"anthropic",?,?,? ,"requested",NOW())')->execute([$publicId,(int)$round['workspace_id'],(int)$round['id'],(int)$actor['id'],$model,'closing_'.$type,mg_investment_json_encode($context)]);$analysisId=(int)$pdo->lastInsertId();try{require_once dirname(__DIR__).'/ai/anthropic-client.php';$system='You are the Microgifter Investor Closing Assistant. Produce an internal editable draft using only the supplied administrative records. Never claim that Microgifter verified identity, accreditation, legal eligibility, signatures, filings, funds, securities issuance, or capitalization beyond explicitly approved records. Do not mark funds received, approve documents, submit filings, sign agreements, process payments, issue securities, or update the official stock ledger. Clearly identify missing facts and counsel/accountant review needs.';$response=mg_anthropic_messages(['model'=>$model,'max_tokens'=>1800,'temperature'=>0.2,'system'=>$system,'messages'=>[['role'=>'user','content'=>mg_investment_json_encode($context)]]]);$text=mg_anthropic_text_from_response($response);$usage=is_array($response['usage']??null)?$response['usage']:[];$pdo->prepare('UPDATE investment_ai_analyses SET response_text=?,status="completed",input_tokens=?,output_tokens=?,completed_at=NOW() WHERE id=?')->execute([$text,(int)($usage['input_tokens']??0),(int)($usage['output_tokens']??0),$analysisId]);mg_audit('investment_closing_ai_completed','investment_ai',['analysis_id'=>$publicId,'draft_type'=>$type],(int)$actor['id']);}catch(Throwable $e){$pdo->prepare('UPDATE investment_ai_analyses SET status="failed",error_message=?,completed_at=NOW() WHERE id=?')->execute([mb_substr($e->getMessage(),0,1000),$analysisId]);}$q=$pdo->prepare('SELECT public_id,analysis_type,response_text,status,error_message,created_at FROM investment_ai_analyses WHERE id=?');$q->execute([$analysisId]);return ['analysis'=>$q->fetch(PDO::FETCH_ASSOC),'dashboard'=>mg_investment_closing_dashboard($pdo,['round_id'=>$round['public_id']])];
}
